CPS_DSCI_ARCHIVE_DATA_CANVAS_TAG_V = """
                use warehouse CPS_DSCI_ETL_EXT2_WH;

               begin;
set update_timestamp = current_timestamp()::timestamp_ntz;
set stage_table_time = to_varchar($update_timestamp, 'yyyy_mm_dd_hh24_mi');
set stage_table_name = CONCAT('CPS_DSCI_STG.DATA_CANVAS_TAG_V_',$stage_table_time);
set max_dim_date = '2150-12-31'::timestamp_ntz;
CREATE or REPLACE TABLE IDENTIFIER($stage_table_name) as  
            SELECT c.TAG_ID,c.TAG_NAME,c.TAG_DESC,c.TAGSET_ID,c.TAGSET_NAME,c.LINK_TAGNAME,c.CREATED_BY,c.CREATE_DTM,c.UPDATED_BY,c.UPDATE_DTM,c.TAG_DEL_FLG,c.COLUMN_NAME,c.LINK_TAG_ID ,
                    MD5(TO_VARCHAR(ARRAY_CONSTRUCT(c.TAG_ID,c.TAG_NAME,c.TAG_DESC,c.TAGSET_ID,c.TAGSET_NAME,c.LINK_TAGNAME,c.CREATED_BY,c.CREATE_DTM,c.UPDATED_BY,c.UPDATE_DTM,c.TAG_DEL_FLG,c.COLUMN_NAME,c.LINK_TAG_ID))) as hash_col
            FROM CPS_BIA_BR.DATA_CANVAS_TAG_V c
             WHERE nvl(TAG_DEL_FLG,'N') = 'N'    ; 

MERGE INTO CPS_DSCI_ARCHIVE.DC_TAG_V_HIST nh
            USING IDENTIFIER($stage_table_name) m  on    nh.TAG_ID =  m.TAG_ID  
                WHEN MATCHED and nh.hash_col <> m.hash_col and  IS_CURRENT = 'T' THEN
                    UPDATE SET nh.LAST_OBSERVATION_TIMESTAMP =$update_timestamp, nh.IS_CURRENT = 'F' ;

INSERT INTO CPS_DSCI_ARCHIVE.DC_TAG_V_HIST 
                        (TAG_ID,TAG_NAME,TAG_DESC,TAGSET_ID,TAGSET_NAME,LINK_TAGNAME,CREATED_BY,CREATE_DTM,UPDATED_BY,UPDATE_DTM,TAG_DEL_FLG,COLUMN_NAME,LINK_TAG_ID, hash_col,  first_observation_timestamp , last_observation_timestamp , is_current )
            SELECT DISTINCT c.TAG_ID,c.TAG_NAME,c.TAG_DESC,c.TAGSET_ID,c.TAGSET_NAME,c.LINK_TAGNAME,c.CREATED_BY,c.CREATE_DTM,c.UPDATED_BY,c.UPDATE_DTM,c.TAG_DEL_FLG,c.COLUMN_NAME,c.LINK_TAG_ID, c.hash_col, $update_timestamp, $max_dim_date, 'T' 
            FROM IDENTIFIER($stage_table_name) c
                 LEFT JOIN CPS_DSCI_ARCHIVE.DC_TAG_V_HIST t ON (t.hash_col=c.HASH_COL)
            WHERE t.HASH_COL is null

                   UNION

            SELECT DISTINCT c.TAG_ID,c.TAG_NAME,c.TAG_DESC,c.TAGSET_ID,c.TAGSET_NAME,c.LINK_TAGNAME,c.CREATED_BY,c.CREATE_DTM,c.UPDATED_BY,c.UPDATE_DTM,c.TAG_DEL_FLG,c.COLUMN_NAME,c.LINK_TAG_ID, c.hash_col, $update_timestamp, $max_dim_date, 'T' 
            FROM IDENTIFIER($stage_table_name) c
                 JOIN CPS_DSCI_ARCHIVE.DC_TAG_V_HIST t ON (t.hash_col=c.HASH_COL)
            WHERE t.IS_CURRENT= 'F'
            AND NOT EXISTS
                  (
                  select 0 from CPS_DSCI_ARCHIVE.DC_TAG_V_HIST x
                  where x.hash_col=c.HASH_COL
                  and  x.IS_CURRENT= 'T'   -- where not already an active record
                )

            ;




            UPDATE CPS_DSCI_ARCHIVE.DC_TAG_V_HIST nh
                SET nh.LAST_OBSERVATION_TIMESTAMP =$update_timestamp, nh.IS_CURRENT = 'F'
            WHERE NOT EXISTS ( 
                -- this is the set that is current.. if not here but in hist it should be expired unless.. its moved to a diff table like..
                SELECT 1 from CPS_BIA_BR.DATA_CANVAS_TAG_V  m
                 WHERE nvl(TAG_DEL_FLG,'N') = 'N'   
                 AND  nh.TAG_ID =  m.TAG_ID  )  and IS_CURRENT ='T' ;

COMMIT;

                """

